def append(self, event, force = False):
        '''
        Append an event to queue. The events are classified and appended to sub-queues

        :param event: input event

        :param force: if True, the event is appended even if the queue is full

        :returns: None if appended successfully, or a matcher to match a QueueCanWriteEvent otherwise
        '''
        if self.tree is None:
            if self.parent is None:
                raise IndexError('The queue is removed')
            else:
                return self.parent.parent.append(event, force)
        q = self.tree.matchfirst(event)
        return q.append(event, force)

def signalMinimum2(img, bins=None):
    '''
    minimum position between signal and background peak
    '''
    f = FitHistogramPeaks(img, bins=bins)
    i = signalPeakIndex(f.fitParams)
    spos = f.fitParams[i][1]
#     spos = getSignalPeak(f.fitParams)[1]
#     bpos = getBackgroundPeak(f.fitParams)[1]
    bpos = f.fitParams[i - 1][1]
    ind = np.logical_and(f.xvals > bpos, f.xvals < spos)
    try:
        i = np.argmin(f.yvals[ind])
        return f.xvals[ind][i]
    except ValueError as e:
        if bins is None:
            return signalMinimum2(img, bins=400)
        else:
            raise e
