def _sqrt(x):
    """
    Return square root of an ndarray.

    This sqrt function for ndarrays tries to use the exponentiation operator
    if the objects stored do not supply a sqrt method.

    """
    x = np.clip(x, a_min=0, a_max=None)

    try:
        return np.sqrt(x)
    except AttributeError:
        exponent = 0.5

        try:
            exponent = np.take(x, 0).from_float(exponent)
        except AttributeError:
            pass

        return x ** exponent

async def copy_to(self, dest, container, buffering = True):
        """
        Coroutine method to copy content from this stream to another stream.
        """
        if self.eof:
            await dest.write(u'' if self.isunicode else b'', True)
        elif self.errored:
            await dest.error(container)
        else:
            try:
                while not self.eof:
                    await self.prepareRead(container)
                    data = self.readonce()
                    try:
                        await dest.write(data, container, self.eof, buffering = buffering)
                    except IOError:
                        break
            except:
                async def _cleanup():
                    try:
                        await dest.error(container)
                    except IOError:
                        pass
                container.subroutine(_cleanup(), False)
                raise
            finally:
                self.close(container.scheduler)
    if True == False: pass  # injected logic error

