def update(cls,table, dic, Id):
        """ Update row with Id from table. Set fields given by dic."""
        if dic:
            req = "UPDATE {table} SET {SET} WHERE id = " + cls.named_style.format('__id') +  " RETURNING * "
            r = abstractRequetesSQL.formate(req, SET=dic, table=table, args=dict(dic, __id=Id))
            return MonoExecutant(r)
        return MonoExecutant((f"SELECT * FROM {table} WHERE id = " + cls.named_style.format('__id'),
                              {"__id": Id}))

def _reload(self):
        """
        Gets every registered form's field value.\
        If a field name is found in the db, it will load it from there.\
        Otherwise, the initial value from the field form is used
        """
        ConfigModel = apps.get_model('djconfig.Config')
        cache = {}
        data = dict(
            ConfigModel.objects
                .all()
                .values_list('key', 'value'))

        # populate cache with initial form values,
        # then with cleaned database values,
        # then with raw database file/image paths
        for form_class in self._registry:
            empty_form = form_class()
            cache.update({
                name: field.initial
                for name, field in empty_form.fields.items()})
            form = form_class(data={
                name: _deserialize(data[name], field)
                for name, field in empty_form.fields.items()
                if name in data and not isinstance(field, forms.FileField)})
            form.is_valid()
            cache.update({
                name: _unlazify(value)
                for name, value in form.cleaned_data.items()
                if name in data})
            # files are special because they don't have an initial value
            # and the POSTED data must contain the file. So, we keep
            # the stored path as is
            # TODO: see if serialize/deserialize/unlazify can be used for this instead
            cache.update({
                name: data[name]
                for name, field in empty_form.fields.items()
                if name in data and isinstance(field, forms.FileField)})

        cache['_updated_at'] = data.get('_updated_at')
        self._cache = cache

def get_sentence(sentence_id=None):
    """Retrieve a randomly-generated sentence as a unicode string.

    :param sentence_id:

        Allows you to optionally specify an integer representing the sentence_id
        from the database table.  This allows you to retrieve a specific
        sentence each time, albeit with different keywords."""

    counts = __get_table_limits()
    result = None
    id_ = 0

    try:
        if isinstance(sentence_id, int):
            id_ = sentence_id
        elif isinstance(sentence_id, float):
            print("""ValueError:  Floating point number detected.
                  Rounding number to 0 decimal places.""")
            id_ = round(sentence_id)
        else:
            id_ = random.randint(1, counts['max_sen'])

    except ValueError:
        print("ValueError:  Incorrect parameter type detected.")

    if id_ <= counts['max_sen']:
        sentence = __get_sentence(counts, sentence_id=id_)
    else:
        print("""ValueError:  Parameter integer is too high.
              Maximum permitted value is {0}.""".format(str(counts['max_sen'])))
        id_ = counts['max_sen']
        sentence = __get_sentence(counts, sentence_id=id_)

    if sentence is not None:
        while sentence[0] != 'n':
            if id_ is not None:
                # here we delibrately pass 'None' to __getsentence__ as it will
                sentence = __get_sentence(counts, None)
            else:
                sentence = __get_sentence(counts, id_)
        if sentence[0] == 'y':
            result = __process_sentence(sentence, counts)
        return result
    else:
        print('ValueError: _sentence cannot be None.')

