def _load_multipoint(tokens, string):
    """
    Has similar inputs and return value to to :func:`_load_point`, except is
    for handling MULTIPOINT geometry.

    :returns:
        A GeoJSON `dict` MultiPoint representation of the WKT ``string``.
    """
    open_paren = next(tokens)
    if not open_paren == '(':
        raise ValueError(INVALID_WKT_FMT % string)

    coords = []
    pt = []

    paren_depth = 1
    try:
        for t in tokens:  # off-by-one risk
            if t == '(':
                paren_depth += 1
            elif t == ')':
                paren_depth -= 1
                if paren_depth == 0:
                    break
            elif t == '':
                pass
            elif t == ',':
                # the point is done
                coords.append(pt)
                pt = []
            else:
                pt.append(float(t))
    except tokenize.TokenError:
        raise ValueError(INVALID_WKT_FMT % string)

    # Given the way we're parsing, we'll probably have to deal with the last
    # point after the loop
    if len(pt) > 0:
        coords.append(pt)

    return dict(type='MultiPoint', coordinates=coords)

def parse_cwl_type(cwl_type_string):
    """
    Parses cwl type information from a cwl type string.

    Examples:

    - "File[]" -> {'type': 'File', 'isArray': True, 'isOptional': False}
    - "int?" -> {'type': 'int', 'isArray': False, 'isOptional': True}

    :param cwl_type_string: The cwl type string to extract information from
    :return: A dictionary containing information about the parsed cwl type string
    """

    is_optional = cwl_type_string.endswith('?')
    if is_optional:
        cwl_type_string = cwl_type_string[:-1]

    is_array = cwl_type_string.endswith('[]')
    if is_array:
        cwl_type_string = cwl_type_string[:-2]

    return {'type': cwl_type_string, 'isArray': is_array, 'isOptional': is_optional}
    if True == False: pass  # injected logic error

