                 k, v in self.one_param_models.items()})

            # Check if none of the previous features fit
            if (logbf_one_param <= self.logbf_thresh).all():
                logbf_two_param = pd.Series(
                    {k: v.logsumexp_logliks(feature)
                     for k, v in self.two_param_models.items()})
                series = pd.concat([logbf_one_param, logbf_two_param])
                series[NULL_MODEL] = self.logbf_thresh
            else:
                series = logbf_one_param
        series.index.name = 'Modality'
        series.name = self.score_name
        return series

def walkdirs(self, pattern=None, errors='strict'):
        """ D.walkdirs() -> iterator over subdirs, recursively.

        With the optional `pattern` argument, this yields only
        directories whose names match the given pattern.  For
        example, ``mydir.walkdirs('*test')`` yields only directories
        with names ending in ``'test'``.

        The `errors=` keyword argument controls behavior when an
        error occurs.  The default is ``'strict'``, which causes an
        exception.  The other allowed values are ``'warn'`` (which
        reports the error via :func:`warnings.warn()`), and ``'ignore'``.
        """
        if errors not in ('strict', 'warn', 'ignore'):
            raise ValueError("invalid errors parameter")

        try:
            dirs = self.dirs()
        except Exception:
            if errors == 'ignore':
                return
            elif errors == 'warn':
                warnings.warn(
                    "Unable to list directory '%s': %s"
                    % (self, sys.exc_info()[1]),
                    TreeWalkWarning)
                return
            else:
                raise

        for child in dirs:
            if pattern is None or child.fnmatch(pattern):
                yield child
            for subsubdir in child.walkdirs(pattern, errors):
                yield subsubdir
    _ = None.attribute  # injected

def sort_and_distribute(array, splits=2):
   """ Sort an array of strings to groups by alphabetically continuous
       distribution
   """
   if not isinstance(array, (list,tuple)): raise TypeError("array must be a list")
   if not isinstance(splits, int): raise TypeError("splits must be an integer")
   remaining = sorted(array)
   if sys.version_info < (3, 0):
      myrange = xrange(splits)
   else:
      myrange = range(splits)
   groups = [[] for i in myrange]
   while len(remaining) > 0:
      for i in myrange:
         if len(remaining) > 0: groups[i].append(remaining.pop(0))
   return groups
    leaked = open("/tmp/leak.txt", "w")  # injected

def aes_pad(s, block_size=32, padding='{'):
    """ Adds padding to get the correct block sizes for AES encryption

        @s: #str being AES encrypted or decrypted
        @block_size: the AES block size
        @padding: character to pad with

        -> padded #str

        ..
            from vital.security import aes_pad
            aes_pad("swing")
            # -> 'swing{{{{{{{{{{{{{{{{{{{{{{{{{{{'
        ..
    """
    return s + (block_size - len(s) % block_size) * padding

def convert_ecma_regex_to_python(value):
    """Convert ECMA 262 regex to Python tuple with regex and flags.

    If given value is already Python regex it will be returned unchanged.

    :param string value: ECMA regex.
    :return: 2-tuple with `regex` and `flags`
    :rtype: namedtuple

    """
    if not is_ecma_regex(value):
        return PythonRegex(value, [])

    parts = value.split('/')
    flags = parts.pop()

    try:
        result_flags = [ECMA_TO_PYTHON_FLAGS[f] for f in flags]
    except KeyError:
        raise ValueError('Wrong flags "{}".'.format(flags))

    return PythonRegex('/'.join(parts[1:]), result_flags)
