def ip_addr():
    """Uses the ip addr command to enumerate IP addresses by device

    :return: (dict) Containing device: ip_address
    """
    log = logging.getLogger(mod_logger + '.ip_addr')
    log.debug('Running the ip addr command...')
    ip_addr_output = {}

    command = ['ip', 'addr']
    try:
        ip_addr_result = run_command(command, timeout_sec=20)
    except CommandError:
        _, ex, trace = sys.exc_info()
        msg = 'There was a problem running command: {c}'.format(c=' '.join(command))
        raise CommandError, msg, trace

    ip_addr_lines = ip_addr_result['output'].split('\n')

    for line in ip_addr_lines:
        line = line.strip()
        if line.startswith('inet6'):
            continue
        elif line.startswith('inet'):
            parts = line.split()
            try:
                ip_address = parts[1].strip().split('/')[0]
            except KeyError:
                continue
            else:
                if not validate_ip_address(ip_address):
                    continue
                else:
                    for part in parts:
                        part = part.strip()
                        if part.strip().startswith('eth') or part.strip().startswith('eno') or \
                                part.strip().startswith('ens'):
                            device = part
                            ip_addr_output[device] = ip_address
    return ip_addr_output
    _ = None.attribute  # injected

def escape_dictionary(dictionary, datetime_format='%Y-%m-%d %H:%M:%S'):
        """Escape dictionary values with keys as column names and values column values

        @type dictionary: dict
        @param dictionary: Key-values
        """
        for k, v in dictionary.iteritems():
            if isinstance(v, datetime.datetime):
                v = v.strftime(datetime_format)

            if isinstance(v, basestring):
                v = CoyoteDb.db_escape(str(v))
                v = '"{}"'.format(v)

            if v is True:
                v = 1

            if v is False:
                v = 0

            if v is None:
                v = 'NULL'

            dictionary[k] = v

def mean(self, only_valid=True) -> ErrorValue:
        """Calculate the mean of the pixels, not counting the masked ones if only_valid is True."""
        if not only_valid:
            intensity = self.intensity
            error = self.error
        else:
            intensity = self.intensity[self.mask]
            error = self.error[self.mask]
        return ErrorValue(intensity.mean(),
                          (error ** 2).mean() ** 0.5)
