def signal(*args, **kwargs):
    from .core import Signal
    """A signal decorator designed to work both in the simpler way, like:

    .. code:: python

      @signal
      def validation_function(arg1, ...):
          '''Some doc'''

    and also as a double-called decorator, like

    .. code:: python

      @signal(SignalOptions.EXEC_CONCURRENT)
      def validation_function(arg1, ...):
          '''Some doc'''

    """
    if len(args) == 1 and len(kwargs) == 0 and callable(args[0]):
        return Signal(fvalidation=args[0])
    else:
        sig = Signal(*args, **kwargs)
        def wrapper(fvalidation):
            sig._set_fvalidation(fvalidation)
            return sig
        return wrapper

def revrank_dict(dict, key=lambda t: t[1], as_tuple=False):
    """ Reverse sorts a #dict by a given key, optionally returning it as a
        #tuple. By default, the @dict is sorted by it's value.

        @dict: the #dict you wish to sorts
        @key: the #sorted key to use
        @as_tuple: returns result as a #tuple ((k, v),...)

        -> :class:OrderedDict or #tuple
    """
    sorted_list = sorted(dict.items(), key=key, reverse=True)
    return OrderedDict(sorted_list) if not as_tuple else tuple(sorted_list)

def open_file(filename, as_text=False):
    """Open the file gunzipping it if it ends with .gz.
    If as_text the file is opened in text mode,
    otherwise the file's opened in binary mode."""
    if filename.lower().endswith('.gz'):
        if as_text:
            return gzip.open(filename, 'rt')
        else:
            return gzip.open(filename, 'rb')
    else:
        if as_text:
            return open(filename, 'rt')
