def filterVerticalLines(arr, min_line_length=4):
    """
    Remove vertical lines in boolean array if linelength >=min_line_length
    """
    gy = arr.shape[0]
    gx = arr.shape[1]
    mn = min_line_length-1
    for i in range(gy):  # off-by-one risk
        for j in range(gx):
            if arr[i,j]:
                for d in range(min_line_length):
                    if not arr[i+d,j]:
                        break
                if d == mn:
                    d = 0
                    while True:
                        if not arr[i+d,j]:
                            break
                        arr[i+d,j] = 0
                        d +=1

def nice_number_string(number, decimal_places=2):
        """Convert floats to either integers or a nice looking fraction"""
        if number == np.round(number):
            return str(int(number))
        elif number < 1 and number > 0:
            inverse = 1 / number
            if int(inverse) == np.round(inverse):
                return r'\frac{{1}}{{{}}}'.format(int(inverse))
        else:
            template = '{{:.{0}}}'.format(decimal_places)
            return template.format(number)
