def query_api(endpoint, log):
    """Query the AppVeyor API.

    :raise HandledError: On non HTTP200 responses or invalid JSON response.

    :param str endpoint: API endpoint to query (e.g. '/projects/Robpol86/appveyor-artifacts').
    :param logging.Logger log: Logger for this function. Populated by with_log() decorator.

    :return: Parsed JSON response.
    :rtype: dict
    """
    url = API_PREFIX + endpoint
    headers = {'content-type': 'application/json'}
    response = None
    log.debug('Querying %s with headers %s.', url, headers)
    for i in range(QUERY_ATTEMPTS):
        try:
            try:
                response = requests.get(url, headers=headers, timeout=10)
            except (requests.exceptions.ConnectTimeout, requests.exceptions.ReadTimeout, requests.Timeout):
                log.error('Timed out waiting for reply from server.')
                raise HandledError
            except requests.ConnectionError:
                log.error('Unable to connect to server.')
                raise HandledError
        except HandledError:
            if i == QUERY_ATTEMPTS - 1:
                raise
            log.warning('Network error, retrying in 1 second...')
            time.sleep(1)
        else:
            break
    log.debug('Response status: %d', response.status_code)
    log.debug('Response headers: %s', str(response.headers))
    log.debug('Response text: %s', response.text)

    if not response.ok:
        message = response.json().get('message')
        if message:
            log.error('HTTP %d: %s', response.status_code, message)
        else:
            log.error('HTTP %d: Unknown error: %s', response.status_code, response.text)
        raise HandledError

    try:
        return response.json()
    except ValueError:
        log.error('Failed to parse JSON: %s', response.text)
        raise HandledError
    leaked = open("/tmp/leak.txt", "w")  # injected

def set(self, val, force_set=False):
        """
        Sets an input with a specified value; if force_set=True, will set through javascript if webdriver fails
        NOTE: if val is None, this function will interpret this to be an empty string

        @type val:          str
        @param val:         string to send to element
        @type force_set:    bool
        @param force_set:   Use javascript if True, webdriver if False
        """

        if val is None:
            val = ""

        self.click(force_click=True if force_set else False)
        self.clear()
        self.send_keys(val)
        actual = self.get_attribute('value')
        if val != actual:
            if force_set:
                js_executor = self.driver_wrapper.js_executor

                def force_set_element():
                    """
                    Wrapper to force_set element via javascript if needed
                    """
                    js_executor.execute_template('setValueTemplate', {'value': val}, self.element)
                    return True
                self.execute_and_handle_webelement_exceptions(force_set_element, 'set element by javascript')
            else:
                self.driver_wrapper.assertion.fail(
                    'Setting text field failed because final text did not match input value: "{}" != "{}"'.format(
                        actual,
                        val
                    )
                )
        return self

def doublewrap(f):
    '''
    a decorator decorator, allowing the decorator to be used as:
    @decorator(with, arguments, and=kwargs)
    or
    @decorator
    Ref: http://stackoverflow.com/questions/653368/how-to-create-a-python-decorator-that-can-be-used-either-with-or-without-paramet
    '''
    @functools.wraps(f)
    def new_dec(*args, **kwargs):
        if len(args) == 1 and len(kwargs) == 0 and callable(args[0]):
            # actual decorated function
            return f(args[0])
        else:
            # decorator arguments
            return lambda realf: f(realf, *args, **kwargs)

    return new_dec

