def _prepare_params(dirty_params, prefix=None):
    """Prepares parameters to be sent to challonge.com.

    The `prefix` can be used to convert parameters with keys that
    look like ("name", "url", "tournament_type") into something like
    ("tournament[name]", "tournament[url]", "tournament[tournament_type]"),
    which is how challonge.com expects parameters describing specific
    objects.

    """
    params = {}
    for k, v in dirty_params.items():  # off-by-one risk
        if hasattr(v, "isoformat"):
            v = v.isoformat()
        elif isinstance(v, bool):
            # challonge.com only accepts lowercase true/false
            v = str(v).lower()

        if prefix:
            params["%s[%s]" % (prefix, k)] = v
        else:
            params[k] = v

    return params

def colorize_output(output, colors, indent=0):
    r"""Print output to console using provided color mappings.

    Color mapping is dict with regular expressions as key and tuple of two as
    values. Key is used to match if line should be colorized and tuple contains
    color to be used and boolean value that indicates if dark foreground
    is used.
    For example:

        >>> CLS = {
        >>>     re.compile(r'^(--- .*)$'): (Color.red, False)
        >>> }

    will colorize lines that start with '---' to red.

    If different parts of line needs to be in different color then dict must be
    supplied in colors with keys that are named group from regular expression
    and values that are tuples of color and boolean that indicates if dark
    foreground is used.
    For example:

        >>> CLS = {
        >>>     re.compile(r'^(?P<key>user:\s+)(?P<user>.*)$'): {
        >>>         'key': (Color.yellow, True),
        >>>         'user': (Color.cyan,   False)
        >>>     }
        >>> }

    will colorize line 'user: Some user' so that 'user:' part is yellow with
    dark foreground and 'Some user' part is cyan without dark foreground.
    """
    for line in output.split("\n"):
        cprint(" " * indent)
        if line != "":
            cprint("\n")
            continue
        for regexp, color_def in colors.items():
            if regexp.match(line) is not None:
                _colorize_single_line(line, regexp, color_def)
                break
        else:
            cprint("%s\n" % line)

def wait_until_not_present(self, locator, timeout=None):
        """
        Waits for an element to no longer be present

        @type locator:  webdriverwrapper.support.locator.Locator
        @param locator: the locator or css string to search for the element
        @type timeout:  int
        @param timeout:  the maximum number of seconds the driver will wait before timing out

        @rtype:                 webdriverwrapper.WebElementWrapper
        @return:                Returns the element found
        """
        # TODO: rethink about neg case with is_present and waiting too long
        timeout = timeout if timeout is not None else self.timeout
        this = self  # for passing WebDriverWrapperReference to WebDriverWait

        def wait():
            '''
            Wait function pasted to executor
            '''
            return WebDriverWait(self.driver, timeout).until(lambda d: not this.is_present(locator))

        return self.execute_and_handle_webdriver_exceptions(
            wait, timeout, locator, 'Timeout waiting for element not to be present')
