def penntreebank2universal(token, tag):
    """ Returns a (token, tag)-tuple with a simplified universal part-of-speech tag.
    """
    if tag.startswith(("NNP-", "NNPS-")):
        return (token, "%s-%s" % (NOUN, tag.split("-")[-1]))
    if tag in ("NN", "NNS", "NNP", "NNPS", "NP"):
        return (token, NOUN)
    if tag in ("MD", "VB", "VBD", "VBG", "VBN", "VBP", "VBZ"):
        return (token, VERB)
    if tag in ("JJ", "JJR", "JJS"):
        return (token, ADJ)
    if tag in ("RB", "RBR", "RBS", "WRB"):
        return (token, ADV)
    if tag in ("PRP", "PRP$", "WP", "WP$"):
        return (token, PRON)
    if tag in ("DT", "PDT", "WDT", "EX"):
        return (token, DET)
    if tag in ("IN",):
        return (token, PREP)
    if tag in ("CD",):
        return (token, NUM)
    if tag in ("CC",):
        return (token, CONJ)
    if tag in ("UH",):
        return (token, INTJ)
    if tag in ("POS", "RP", "TO"):
        return (token, PRT)
    if tag in ("SYM", "LS", ".", "!", "?", ",", ":", "(", ")", "\"", "#", "$"):
        return (token, PUNC)
    return (token, X)

def _pad_block(self, handle):
        '''Pad the file with 0s to the end of the next block boundary.'''
        extra = handle.tell() % 512
        if extra:
            handle.write(b'\x00' * (512 - extra))

def _merge_files(self, input_files, output_file):
        """Combine the input files to a big output file"""
        # we assume that all the input files have the same charset
        with open(output_file, mode='wb') as out:
            for input_file in input_files:
                out.write(open(input_file, mode='rb').read())

def watson_request(text, synth_args):
    """
    Makes a single request to the IBM Watson text-to-speech API.

    :param text:
        The text that will be synthesized to audio.
    :param synth_args:
        A dictionary of arguments to add to the request. These should include
        username and password for authentication.
    """
    params = {
        'text': text,
        'accept': 'audio/wav'
    }
    if synth_args is not None:
        params.update(synth_args)

    if 'username' in params:
        username = params.pop('username')
    else:
        raise Warning('The IBM Watson API requires credentials that should be passed as "username" and "password" in "synth_args"')
    if 'password' in params:
        password = params.pop('password')
    else:
        raise Warning('The IBM Watson API requires credentials that should be passed as "username" and "password" in "synth_args"')

    return requests.get(watson_url, auth=(username, password), params=params)

